CREATE TABLE "AuctionRound" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "roundNumber" INTEGER NOT NULL, "status" TEXT NOT NULL, "inputSnapshotId" TEXT, "inputHash" TEXT, "contractVersion" TEXT, "publishedAt" TEXT, "supersededAt" TEXT, FOREIGN KEY ("seasonId") REFERENCES "Season"("id"), UNIQUE("seasonId", "roundNumber", "supersededAt"));
CREATE TABLE "AuctionSubmission" ("id" TEXT NOT NULL PRIMARY KEY, "roundId" TEXT NOT NULL, "seasonTeamId" TEXT NOT NULL, "status" TEXT NOT NULL, "zeroConfirmed" INTEGER NOT NULL DEFAULT 0, "bidsJson" TEXT NOT NULL, "bidCount" INTEGER NOT NULL, "updatedAt" TEXT NOT NULL, FOREIGN KEY ("roundId") REFERENCES "AuctionRound"("id"), UNIQUE("roundId", "seasonTeamId"));
CREATE TABLE "AuctionAttempt" ("id" TEXT NOT NULL PRIMARY KEY, "roundId" TEXT NOT NULL, "attemptNumber" INTEGER NOT NULL, "inputJson" TEXT NOT NULL, "inputHash" TEXT NOT NULL, "outputJson" TEXT NOT NULL, "outputHash" TEXT NOT NULL, "eliminationsJson" TEXT NOT NULL, "traceJson" TEXT NOT NULL, "status" TEXT NOT NULL, "contractVersion" TEXT NOT NULL, "createdAt" TEXT NOT NULL, "supersededAt" TEXT, FOREIGN KEY ("roundId") REFERENCES "AuctionRound"("id"), UNIQUE("roundId", "attemptNumber"));
CREATE TABLE "AuctionTieDecision" ("id" TEXT NOT NULL PRIMARY KEY, "roundId" TEXT NOT NULL, "tieKey" TEXT NOT NULL, "playerId" TEXT NOT NULL, "amount" INTEGER NOT NULL, "participantTeamIdsJson" TEXT NOT NULL, "preferredTeamId" TEXT NOT NULL, "method" TEXT NOT NULL, "note" TEXT, "decidedAt" TEXT NOT NULL, "supersededAt" TEXT, FOREIGN KEY ("roundId") REFERENCES "AuctionRound"("id"));
CREATE TABLE "AuctionAward" ("id" TEXT NOT NULL PRIMARY KEY, "roundId" TEXT NOT NULL, "seasonTeamId" TEXT NOT NULL, "playerId" TEXT NOT NULL, "amount" INTEGER NOT NULL, "bidId" TEXT NOT NULL, "sourceAttemptId" TEXT NOT NULL, FOREIGN KEY ("roundId") REFERENCES "AuctionRound"("id"), UNIQUE("roundId", "playerId"));
CREATE TABLE "TeamAuctionBalance" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "seasonTeamId" TEXT NOT NULL, "roundNumber" INTEGER NOT NULL, "startingBudget" INTEGER NOT NULL, "spent" INTEGER NOT NULL, "remainingBudget" INTEGER NOT NULL, UNIQUE("seasonId", "seasonTeamId", "roundNumber"));
CREATE TABLE "RosterAssignment" ("id" TEXT NOT NULL PRIMARY KEY, "seasonId" TEXT NOT NULL, "seasonTeamId" TEXT NOT NULL, "playerId" TEXT NOT NULL, "acquisitionSource" TEXT NOT NULL, "auctionRound" INTEGER, "cost" INTEGER, "sourceEntityId" TEXT NOT NULL, "supersededAt" TEXT, UNIQUE("seasonId", "playerId", "supersededAt"));
UPDATE "SchemaMetadata" SET "version"=3, "applicationVersion"='0.3.0' WHERE "singleton"=1;
